import{_ as s,l as o,o as e,c as i,v as l,p as n,x as r,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"访存级并行 MLP","description":"","frontmatter":{"title":"访存级并行 MLP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mlp-memory-parallelism.md","filePath":"cs/mlp-memory-parallelism.md","lastUpdated":1789023840000}'),c={name:"cs/mlp-memory-parallelism.md"};function h(A,a,P,M,E,_){const t=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=l('<h1 id="访存级并行-mlp" tabindex="-1">访存级并行 MLP <a class="header-anchor" href="#访存级并行-mlp" aria-label="Permalink to &quot;访存级并行 MLP&quot;">​</a></h1><div class="epigraph"><p>DRAM 延迟以百拍计；一条 load 卡住窗口时，若还能再发出几条独立缺失，有效延迟就被重叠摊薄。</p><footer>—— 据 Glew 对 MLP 的命名；Chou, Jaleel, and Shen；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/victim-cache">上一课</a> 减少冲突往返。<a href="/cs/mshr">MSHR</a> 已经允许同一时刻登记多个未完成块请求。本课不重画牺牲缓存。缺口是把**访存级并行（memory-level parallelism）**说成乱序核与 cache 层次的共同目标：窗口、ROB、MSHR、SQ 必须一起够大，才能让多趟 DRAM 重叠。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单条 load 缺失的 CPI 贡献 ≈ 延迟。若窗口里还有独立的 load，它们的缺失可以同时飞，摊到每条指令上的平均延迟变成 \\(T / \\mathrm{MLP}\\)。指针追逐 MLP≈1：数据依赖链把第二次地址算死。数组扫描可以很大。缺口不是再加一路 L1，而是<strong>量化「同时未完成的缺失数」，并承认结构上限会先碰到。</strong></p><p><span class="marginnote">MLP 与 ILP 不同：ILP 是每拍完成几条指令，MLP 是同时有几趟访存在飞行。乱序的一大收益是提高 MLP，而不只是把 ALU 排满。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MSHR 项数、未完成 L2/L3 miss 数、DRAM 控制器队列，取最小者为硬件 MLP 上限。编译与算法：把独立访存排进同一窗口（循环展开、软件流水），避免不必要的锁链。指针结构用预取或数据布局提高有效 MLP。</p>',8)),(e(),n(p,null,{default:r(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIN%5B%22%E4%B9%B1%E5%BA%8F%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20LD%5B%22%E5%A4%9A%E6%9D%A1%E7%8B%AC%E7%AB%8B%20load%22%5D%0A%20%20LD%20--%3E%20MSHR%5B%22%E5%A4%9A%E4%B8%AA%20MSHR%22%5D%0A%20%20MSHR%20--%3E%20DRAM%5B%22%E9%87%8D%E5%8F%A0%20DRAM%20%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20DEP%5B%22%E5%9C%B0%E5%9D%80%E4%BE%9D%E8%B5%96%E9%93%BE%22%5D%20--%3E%20ONE%5B%22MLP%20%E6%8E%A5%E8%BF%91%201%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/retire-precise-exception">退休</a> 头若被最年长的 miss 堵住，ROB 满会阻止更年轻的独立 load 进入窗口，MLP 上不去——「精确提交」与「重叠缺失」在这里打架。有的设计允许 miss 的 load 退休到一个更大的缓冲，但那放松的是实现，不是本课要改的 ISA 精确性定义。</p><p>预取把强制缺失变成提前的 MSHR 占用，看起来像提高 MLP，其实是把未来的需求拉进现在；错预取挤占真 MLP。下一课步长预取器专门发这些提前请求。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GPU 的大量 outstanding request 写成 CPU ROB 的替代——SIMT 有另一套延迟隐藏，后课。也不把量化交易系统的撮合延迟拉进来。目录协议的转发链会拉长单次 miss，降低有效 MLP。</p><p>后课默认：CPI 的访存项看延迟/MLP。有规律的地址流应该用预取去占 MSHR，而不是等需求 miss。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MLP 是同时飞行的缺失数；乱序窗口与 MSHR 共同设上限。</li><li>ROB 头阻塞会扼杀 MLP。</li><li>步长与流预取是下一课主动提高飞行中请求的手段。</li><li>出处：Glew；Chou, Jaleel, Shen；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const u=s(c,[["render",h]]);export{B as __pageData,u as default};
